#!/usr/bin/env bash
set -uo pipefail

if [[ ${EUID} -ne 0 ]]; then
  echo "Run this command with sudo: sudo rf-monitor doctor" >&2
  exit 1
fi

STATE_FILE="${RFMON_STATE_FILE:-/etc/rf-monitor/install.conf}"
[[ -r "${STATE_FILE}" ]] || { echo "FAIL  Installation state not found: ${STATE_FILE}"; exit 1; }
# This file is generated by the installer and owned by root.
source "${STATE_FILE}"

CHECK_SPECTRUM=false
[[ "${1:-}" == "--spectrum" ]] && CHECK_SPECTRUM=true
pass_count=0
warn_count=0
fail_count=0
hardware_pending=false

pass() { printf 'PASS  %s\n' "$*"; pass_count=$((pass_count + 1)); }
warn() { printf 'WARN  %s\n' "$*"; warn_count=$((warn_count + 1)); }
fail() { printf 'FAIL  %s\n' "$*"; fail_count=$((fail_count + 1)); }
section() { printf '\n[%s]\n' "$*"; }

config_value() {
  local key="$1" fallback="${2:-}" line value
  line="$(grep -E "^${key}=" "${CONFIG_FILE}" 2>/dev/null | tail -n 1 || true)"
  [[ -n "${line}" ]] || { printf '%s' "${fallback}"; return; }
  value="${line#*=}"
  if [[ "${value}" == \"*\" && "${value}" == *\" ]]; then
    value="${value:1:${#value}-2}"
    value="${value//\\\"/\"}"
    value="${value//\\\\/\\}"
  fi
  printf '%s' "${value}"
}

CONFIG_ENV=()
load_config_environment() {
  local line key value
  CONFIG_ENV=()
  while IFS= read -r line || [[ -n "${line}" ]]; do
    [[ -z "${line}" || "${line}" == \#* || "${line}" != *=* ]] && continue
    key="${line%%=*}"
    value="${line#*=}"
    [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || continue
    if [[ "${value}" == \"*\" && "${value}" == *\" ]]; then
      value="${value:1:${#value}-2}"
      value="${value//\\\"/\"}"
      value="${value//\\\\/\\}"
    fi
    CONFIG_ENV+=("${key}=${value}")
  done < "${CONFIG_FILE}"
}

section "Operating system and clock"
if [[ -r /etc/os-release ]]; then
  os_name="$(. /etc/os-release; printf '%s %s' "${NAME:-Linux}" "${VERSION_ID:-unknown}")"
  if [[ "${os_name}" == "Ubuntu 24.04" ]]; then pass "Ubuntu 24.04 detected."; else warn "Expected Ubuntu 24.04; found ${os_name}."; fi
else
  fail "Cannot read /etc/os-release."
fi

if grep -qi microsoft /proc/sys/kernel/osrelease 2>/dev/null; then
  fail "WSL detected. This host is a software test lab only; production evidence acceptance requires native Ubuntu hardware, an independently synchronized clock, and a directly attached SDRplay."
fi

if [[ "$(timedatectl show --property=NTPSynchronized --value 2>/dev/null)" == "yes" ]]; then
  pass "System clock is synchronized: $(date --utc --iso-8601=seconds)"
else
  fail "System clock is not synchronized. Run 'sudo timedatectl set-ntp true', wait two minutes, then run doctor again."
fi

section "Installed software"
if [[ -x "${NODE_BIN}" ]]; then
  node_major="$("${NODE_BIN}" -p 'process.versions.node.split(".")[0]' 2>/dev/null)"
  if [[ "${node_major}" =~ ^[0-9]+$ ]] && (( node_major >= 20 )); then pass "Node.js $("${NODE_BIN}" --version) is supported."; else fail "Node.js 20 or newer is required."; fi
else
  fail "Node.js executable not found: ${NODE_BIN}"
fi
[[ -f "${INSTALL_DIR}/dist/server-node/index.js" ]] && pass "RF Monitor production build is installed." || fail "RF Monitor build is missing. Re-run the installer."
[[ -f "${INSTALL_DIR}/dist/server-node/evidence-verifier.js" ]] && pass "Offline evidence verifier is installed." || fail "Offline evidence verifier is missing. Re-run the installer."
[[ -x "${SDRCONNECT_BIN:-/opt/sdrconnect/SDRconnect_headless}" ]] && pass "SDRconnect headless executable is installed." || fail "SDRconnect headless is missing. Install SDRconnect, then re-run the installer."

section "SDRplay hardware"
if lsusb -d 1df7: 2>/dev/null | grep -q .; then
  while IFS= read -r device; do pass "Detected ${device}."; done < <(lsusb -d 1df7:)
else
  hardware_pending=true
  if [[ "${CHECK_SPECTRUM}" == "true" ]]; then
    fail "No directly attached SDRplay USB device was detected. Connect the RSP, confirm it appears in lsusb, then retry commissioning."
  else
    warn "No SDRplay USB device is attached. Software checks can finish, but hardware commissioning remains pending."
  fi
fi

section "Configuration"
if [[ -r "${CONFIG_FILE}" ]]; then
  permissions="$(stat -c '%a' "${CONFIG_FILE}" 2>/dev/null)"
  owner="$(stat -c '%U:%G' "${CONFIG_FILE}" 2>/dev/null)"
  [[ "${permissions}" == "600" && "${owner}" == "root:root" ]] && pass "Configuration file is protected (root:root, mode 600)." || fail "${CONFIG_FILE} should be root:root with mode 600; found ${owner}, mode ${permissions}."
  if grep -Eq 'CHANGE_ME|<[^>]+>' "${CONFIG_FILE}"; then fail "Configuration still contains a placeholder. Run 'sudo rf-monitor configure'."; else pass "No placeholder values remain."; fi
  load_config_environment
  validation_output="$(runuser -u "${SERVICE_USER}" -- env "${CONFIG_ENV[@]}" "${NODE_BIN}" "${INSTALL_DIR}/dist/server-node/validate-config.js" 2>&1)"
  if [[ $? -eq 0 ]]; then pass "Application configuration passes validation."; else fail "Configuration validation failed: ${validation_output}"; fi
else
  fail "Configuration file is missing: ${CONFIG_FILE}. Run 'sudo rf-monitor configure'."
fi

catalog_file="$(config_value RF_MONITOR_CATALOG_FILE "${CATALOG_FILE:-}")"
operational_file="$(config_value RF_MONITOR_OPERATIONAL_FILE "${OPERATIONAL_FILE:-}")"
admin_file="$(config_value RF_MONITOR_ADMIN_FILE "${ADMIN_FILE:-}")"
qualification_approval_file="$(config_value RFMON_QUALIFICATION_APPROVAL_FILE "/etc/rf-monitor/qualification-approval-v1.json")"
[[ -n "${catalog_file}" && -r "${catalog_file}" ]] && pass "Versioned frequency catalog is readable: ${catalog_file}" || fail "Frequency catalog is missing or unreadable. Re-run the installer."
[[ -n "${operational_file}" && -r "${operational_file}" ]] && pass "Operational profile is readable: ${operational_file}" || fail "Operational profile is missing or unreadable. Run 'sudo rf-monitor configure'."
[[ -n "${admin_file}" && -r "${admin_file}" ]] && pass "Settings credential file is readable by the service group." || fail "Settings password is not configured. Run 'sudo rf-monitor reset-admin-password'."
if [[ -r "${qualification_approval_file}" ]]; then
  qualification_approval_owner="$(stat -c '%U:%G' "${qualification_approval_file}" 2>/dev/null)"
  qualification_approval_mode="$(stat -c '%a' "${qualification_approval_file}" 2>/dev/null)"
  if [[ "${qualification_approval_owner}" == "root:${SERVICE_GROUP}" && "${qualification_approval_mode}" == "640" ]] \
    && runuser -u "${SERVICE_USER}" -- test -r "${qualification_approval_file}" \
    && ! runuser -u "${SERVICE_USER}" -- test -w "${qualification_approval_file}"; then
    pass "External qualification approval is root-owned and read-only to RF Monitor."
  else
    fail "${qualification_approval_file} must be root:${SERVICE_GROUP}, mode 640, readable but not writable by ${SERVICE_USER}."
  fi
else
  warn "External qualification approval is not installed. Local health and soak progress cannot produce Production ready."
fi
if [[ -n "${operational_file}" && -r "${operational_file}" ]]; then
  operational_owner="$(stat -c '%U:%G' "${operational_file}" 2>/dev/null)"
  operational_mode="$(stat -c '%a' "${operational_file}" 2>/dev/null)"
  [[ "${operational_owner}" == "${SERVICE_USER}:${SERVICE_GROUP}" && "${operational_mode}" == "640" ]] \
    && pass "Operational profile has protected writable ownership." \
    || fail "${operational_file} should be ${SERVICE_USER}:${SERVICE_GROUP}, mode 640; found ${operational_owner}, mode ${operational_mode}."
fi
if [[ -n "${admin_file}" && -r "${admin_file}" ]]; then
  admin_owner="$(stat -c '%U:%G' "${admin_file}" 2>/dev/null)"
  admin_mode="$(stat -c '%a' "${admin_file}" 2>/dev/null)"
  [[ "${admin_owner}" == "root:${SERVICE_GROUP}" && "${admin_mode}" == "640" ]] \
    && pass "Settings credential is root-owned and not stored in the environment file." \
    || fail "${admin_file} should be root:${SERVICE_GROUP}, mode 640; found ${admin_owner}, mode ${admin_mode}."
fi
[[ "$(config_value RF_MONITOR_REQUIRE_EXPLICIT_CONFIG false)" == "true" ]] && pass "Strict no-hardcode production mode is enabled." || fail "RF_MONITOR_REQUIRE_EXPLICIT_CONFIG must be true in production."
[[ "$(config_value RF_MONITOR_SIMULATION off)" == "off" ]] && pass "Simulation is disabled." || fail "Simulation is enabled; this must not be used as production evidence."

section "Evidence storage"
storage_dir="$(config_value RF_MONITOR_STORAGE "${STORAGE_DIR}")"
if [[ -d "${storage_dir}" ]]; then
  pass "Evidence directory exists: ${storage_dir}"
  if runuser -u "${SERVICE_USER}" -- test -w "${storage_dir}"; then pass "RF Monitor can write to the evidence directory."; else fail "RF Monitor cannot write to ${storage_dir}. Run 'sudo chown -R ${SERVICE_USER}:${SERVICE_GROUP} ${storage_dir}'."; fi
  available_bytes="$(df -PB1 "${storage_dir}" | awk 'NR==2 {print $4}')"
  minimum_bytes="$(jq -r '.retention.minimumFreeBytes // 0' "${operational_file}" 2>/dev/null || echo 0)"
  if [[ "${available_bytes}" =~ ^[0-9]+$ && "${minimum_bytes}" =~ ^[0-9]+$ && ${available_bytes} -ge ${minimum_bytes} ]]; then
    pass "Free disk space is above the configured reserve ($(numfmt --to=iec "${available_bytes}") available)."
  else
    fail "Free disk space is below the configured reserve. Remove or archive old evidence."
  fi
else
  fail "Evidence directory does not exist: ${storage_dir}"
fi

section "System log recycling"
journal_config="${JOURNAL_CONFIG_FILE:-/etc/systemd/journald.conf.d/rf-monitor.conf}"
if [[ -r "${journal_config}" ]]; then
  expected_journal_max="${JOURNAL_MAX_USE_MIB:-512}"
  expected_journal_free="${JOURNAL_KEEP_FREE_MIB:-1024}"
  expected_journal_days="${JOURNAL_RETENTION_DAYS:-14}"
  if grep -Fxq "SystemMaxUse=${expected_journal_max}M" "${journal_config}" \
    && grep -Fxq "SystemKeepFree=${expected_journal_free}M" "${journal_config}" \
    && grep -Fxq "MaxRetentionSec=${expected_journal_days}day" "${journal_config}"; then
    pass "System journal recycling is configured (${expected_journal_max} MiB maximum, ${expected_journal_days} days)."
  else
    fail "System journal policy differs from the generated installation state. Run 'sudo rf-monitor configure'."
  fi
else
  fail "System journal recycling policy is missing. Run 'sudo rf-monitor configure'."
fi
systemctl is-active --quiet systemd-journald.service && pass "systemd-journald is running: $(journalctl --disk-usage 2>/dev/null)" || fail "systemd-journald is not running."

section "SDRconnect"
if systemctl is-active --quiet sdrconnect-headless.service; then pass "sdrconnect-headless.service is running."; else fail "SDRconnect headless service is not running. Check 'sudo rf-monitor logs'."; fi

section "Receiver recovery supervision"
recovery_status_file="${RFMON_RECOVERY_STATUS_FILE:-/run/rf-monitor-recovery/status.json}"
recovery_verifier="${INSTALL_DIR}/deploy/verify-recovery-supervisor.sh"
recovery_verifier_exit=1
recovery_verifier_failures=0
if [[ -x "${recovery_verifier}" ]]; then
  recovery_verification_output="$(env \
    RFMON_INSTALL_DIR="${INSTALL_DIR}" \
    RFMON_CONFIG_FILE="${CONFIG_FILE}" \
    RFMON_RECOVERY_STATUS_FILE="${recovery_status_file}" \
    bash "${recovery_verifier}" 2>&1)"
  recovery_verifier_exit=$?
  while IFS= read -r recovery_verification_line; do
    case "${recovery_verification_line}" in
      "PASS  "*) pass "${recovery_verification_line#PASS  }" ;;
      "FAIL  "*) fail "${recovery_verification_line#FAIL  }"; recovery_verifier_failures=$((recovery_verifier_failures + 1)) ;;
      "" ) ;;
      *) fail "Recovery supervisor verifier could not interpret: ${recovery_verification_line}"; recovery_verifier_failures=$((recovery_verifier_failures + 1)) ;;
    esac
  done <<< "${recovery_verification_output}"
  if [[ "${recovery_verifier_exit}" -ne 0 && "${recovery_verifier_failures}" -eq 0 ]]; then
    fail "Receiver recovery supervisor verification did not complete. Re-run the installer."
  fi
else
  fail "Receiver recovery supervisor verifier is missing. Re-run the installer."
fi

if [[ "${recovery_verifier_exit}" -eq 0 ]]; then
  recovery_state="$(jq -r '.state' "${recovery_status_file}")"
  recovery_reason="$(jq -r '.reasonCode' "${recovery_status_file}")"
  case "${recovery_state}" in
    live)
      pass "Receiver recovery helper reports Live (${recovery_reason})."
      ;;
    requested|recovering)
      warn "Receiver recovery helper reports ${recovery_state} (${recovery_reason}). Wait one minute, then run doctor again."
      ;;
    failed)
      if [[ "${recovery_reason}" == "hardware-absent" && "${CHECK_SPECTRUM}" != "true" ]]; then
        warn "Receiver recovery helper reports failed (${recovery_reason}); hardware commissioning remains pending."
      else
        fail "Receiver recovery helper reports failed (${recovery_reason}). Check USB power and 'sudo rf-monitor logs 200', then use Retry receiver once."
      fi
      ;;
    lockout)
      recovery_lockout_until="$(jq -r '.lockoutUntil // "not reported"' "${recovery_status_file}")"
      fail "Receiver recovery is locked after bounded attempts (until ${recovery_lockout_until}). Check USB power and service logs before retrying."
      ;;
  esac
fi

section "Application heartbeat supervision"
application_recovery_status_file="${RFMON_APPLICATION_RECOVERY_STATUS_FILE:-/run/rf-monitor-application-recovery/status.json}"
if systemctl is-enabled --quiet rf-monitor-application-recovery.timer \
  && systemctl is-active --quiet rf-monitor-application-recovery.timer; then
  pass "Application heartbeat timer is active."
else
  fail "Application heartbeat timer is not active. Re-run the installer."
fi
if [[ -r "${application_recovery_status_file}" ]] && jq -e '.schemaVersion == 1 and (.state | IN("live","requested","recovering","failed","lockout")) and (.reasonCode | type == "string")' "${application_recovery_status_file}" >/dev/null 2>&1; then
  application_recovery_state="$(jq -r '.state' "${application_recovery_status_file}")"
  application_recovery_reason="$(jq -r '.reasonCode' "${application_recovery_status_file}")"
  case "${application_recovery_state}" in
    live) pass "Application heartbeat is Live (${application_recovery_reason})." ;;
    requested|recovering) warn "Application recovery reports ${application_recovery_state} (${application_recovery_reason}). Wait one minute, then run doctor again." ;;
    failed) fail "Application recovery failed (${application_recovery_reason}). Run 'sudo rf-monitor logs 200'." ;;
    lockout)
      application_lockout_until="$(jq -r '.lockoutUntil // "not reported"' "${application_recovery_status_file}")"
      fail "Application recovery is locked after bounded attempts (until ${application_lockout_until}). Run 'sudo rf-monitor logs 200'."
      ;;
  esac
else
  fail "Application heartbeat status is missing or invalid. Re-run the installer."
fi

primary_sdr_url="$(config_value SDRCONNECT_URL ws://127.0.0.1:5454/)"
configured_sdr_urls="$(config_value SDRCONNECT_URLS "${primary_sdr_url}")"
configured_sdr_urls="${configured_sdr_urls//[[:space:]]/}"
IFS=',' read -r -a sdr_urls <<< "${configured_sdr_urls}"
SDR_LOCAL_PORTS=()
RF_MONITOR_STOPPED_FOR_SPECTRUM=false
if [[ "${CHECK_SPECTRUM}" == "true" ]] && systemctl is-active --quiet rf-monitor.service; then
  systemctl stop rf-monitor.service
  RF_MONITOR_STOPPED_FOR_SPECTRUM=true
  trap 'if [[ "${RF_MONITOR_STOPPED_FOR_SPECTRUM:-false}" == "true" ]]; then systemctl start rf-monitor.service >/dev/null 2>&1 || true; fi' EXIT
  pass "RF Monitor was paused so the commissioning verifier has exclusive SDR control."
fi
for receiver_index in "${!sdr_urls[@]}"; do
  receiver_number=$(( receiver_index + 1 ))
  sdr_url="${sdr_urls[receiver_index]}"
  endpoint_data="$("${NODE_BIN}" -e 'try { const u=new URL(process.argv[1]); console.log(`${u.hostname}\t${u.port || (u.protocol === "wss:" ? "443" : "80")}`); } catch { process.exit(1); }' "${sdr_url}" 2>/dev/null)"
  sdr_host="${endpoint_data%%$'\t'*}"
  sdr_port="${endpoint_data#*$'\t'}"
  if [[ "${sdr_host}" == "127.0.0.1" || "${sdr_host}" == "localhost" || "${sdr_host}" == "[::1]" ]]; then
    SDR_LOCAL_PORTS+=("${sdr_port}")
    if ss -ltnH | awk '{print $4}' | grep -Eq "[:.]${sdr_port}$"; then pass "Receiver ${receiver_number}: a process is listening on local port ${sdr_port}."; else fail "Receiver ${receiver_number}: nothing is listening on local port ${sdr_port}."; fi
    listener_pid="$(ss -ltnpH "sport = :${sdr_port}" 2>/dev/null | sed -nE 's/.*pid=([0-9]+).*/\1/p' | head -n 1)"
    managed_pid="$(systemctl show --property=MainPID --value sdrconnect-headless.service 2>/dev/null || true)"
    if [[ -n "${listener_pid}" && "${listener_pid}" != "0" && "${listener_pid}" != "${managed_pid}" ]]; then
      listener_name="$(ps -p "${listener_pid}" -o comm= 2>/dev/null || echo unknown)"
      fail "Receiver ${receiver_number}: port ${sdr_port} belongs to ${listener_name} (PID ${listener_pid}), not sdrconnect-headless.service. Close SDRconnect GUI; RF Monitor will not stop it automatically."
    elif [[ -n "${listener_pid}" ]]; then
      pass "Receiver ${receiver_number}: local API port ${sdr_port} is owned by the managed headless service (PID ${listener_pid})."
    fi
  else
    warn "Receiver ${receiver_number} uses remote SDRconnect host ${sdr_host}; verify that link is protected and approved."
  fi

  verify_output="$(runuser -u "${SERVICE_USER}" -- env SDRCONNECT_URL="${sdr_url}" SDRCONNECT_DEVICE_INDEX="$(config_value SDRCONNECT_DEVICE_INDEX 0)" SDRCONNECT_VERIFY_TIMEOUT_MS=4000 "${NODE_BIN}" "${INSTALL_DIR}/scripts/verify-sdrconnect.mjs" 2>&1)"
  if [[ $? -eq 0 ]]; then
    pass "Receiver ${receiver_number}: SDRconnect JSON WebSocket API responded."
    active_device="$(printf '%s' "${verify_output}" | jq -r '.activeDevice // empty' 2>/dev/null)"
    if ! printf '%s' "${verify_output}" | jq -e '.readiness.device == true' >/dev/null 2>&1; then
      hardware_pending=true; if [[ "${CHECK_SPECTRUM}" == "true" ]]; then fail "Receiver ${receiver_number}: exact RSPdx/RSPdx R2 model and serial identity were not confirmed; SDRconnect reports '${active_device:-no active device}'."; else warn "Receiver ${receiver_number}: SDRconnect API is ready, but exact RSPdx/RSPdx R2 model and serial identity are pending."; fi
    else
      pass "Receiver ${receiver_number}: supported receiver model and serial identity are confirmed (${active_device})."
    fi
  else
    fail "Receiver ${receiver_number}: SDRconnect JSON API check failed. Details: ${verify_output}"
  fi

  if [[ "${CHECK_SPECTRUM}" == "true" ]]; then
    spectrum_output="$(runuser -u "${SERVICE_USER}" -- env SDRCONNECT_URL="${sdr_url}" SDRCONNECT_DEVICE_INDEX="$(config_value SDRCONNECT_DEVICE_INDEX 0)" SDRCONNECT_VERIFY_TIMEOUT_MS=10000 "${NODE_BIN}" "${INSTALL_DIR}/scripts/verify-sdrconnect.mjs" --spectrum 2>&1)"
    if [[ $? -eq 0 ]]; then pass "Receiver ${receiver_number}: a real binary spectrum frame was received."; else fail "Receiver ${receiver_number}: no real spectrum frame was received. Confirm the source is a physical RSP, not IQ File. Details: ${spectrum_output}"; fi
  fi
done
if [[ "${RF_MONITOR_STOPPED_FOR_SPECTRUM}" == "true" ]]; then
  RF_MONITOR_RETURNED_LIVE=false
  systemctl start rf-monitor.service
  for readiness_attempt in $(seq 1 30); do
    health_probe="$(curl --silent --max-time 2 "http://127.0.0.1:$(config_value RF_MONITOR_PORT 8080)/api/health" 2>/dev/null || true)"
    if echo "${health_probe}" | jq -e '.monitoringReady == true' >/dev/null 2>&1; then RF_MONITOR_RETURNED_LIVE=true; break; fi
    sleep 1
  done
  RF_MONITOR_STOPPED_FOR_SPECTRUM=false
  trap - EXIT
  if [[ "${RF_MONITOR_RETURNED_LIVE}" == "true" ]]; then pass "RF Monitor returned to live monitoring after exclusive spectrum verification."; else fail "RF Monitor did not return to live monitoring within 30 seconds after spectrum verification."; fi
fi
if [[ "${CHECK_SPECTRUM}" != "true" ]]; then
  warn "Real spectrum was not tested. Run 'sudo rf-monitor doctor --spectrum' during commissioning."
fi
sdr_port="${SDR_LOCAL_PORTS[0]:-unknown}"

section "RF Monitor service"
if systemctl is-active --quiet rf-monitor.service; then pass "rf-monitor.service is running."; else fail "rf-monitor.service is not running. Check 'sudo rf-monitor logs'."; fi
backend_port="$(config_value RF_MONITOR_PORT 8080)"
health_output="$(curl --silent --show-error --max-time 5 "http://127.0.0.1:${backend_port}/api/health" 2>&1)"
if [[ $? -eq 0 ]] && echo "${health_output}" | jq -e '.schemaVersion == 2 and (.summary.state == "normal" or .summary.state == "attention" or .summary.state == "critical" or .summary.state == "simulation")' >/dev/null 2>&1; then
  health_summary_state="$(echo "${health_output}" | jq -r '.summary.state')"
  health_issue_count="$(echo "${health_output}" | jq -r '.summary.issues | length')"
  case "${health_summary_state}" in
    normal) pass "Loopback health endpoint reports Normal." ;;
    attention) warn "Loopback health endpoint reports Attention (${health_issue_count} diagnostic issue(s)). Open Settings > System health." ;;
    simulation) warn "Loopback health endpoint reports Simulation. Physical receiver hardware is not tested." ;;
    critical) fail "Loopback health endpoint reports Critical (${health_issue_count} diagnostic issue(s)). Open Settings > System health before commissioning." ;;
  esac
  if echo "${health_output}" | jq -e '.identity.release.integrity == "release-metadata" and (.identity.release.sourceDigest | test("^[a-f0-9]{64}$")) and (.identity.release.packageDigest | test("^[a-f0-9]{64}$")) and (.identity.release.dependencyLockDigest | test("^[a-f0-9]{64}$"))' >/dev/null; then
    pass "Immutable release identity is present ($(echo "${health_output}" | jq -r '.identity.release.buildId'))."
  else
    fail "Release identity is runtime-derived or incomplete. Install an immutable package with recorded source, package, and dependency-lock digests."
  fi
  production_ready_filter="${INSTALL_DIR}/deploy/production-ready.jq"
  if [[ -r "${production_ready_filter}" ]] && echo "${health_output}" | jq -e -f "${production_ready_filter}" >/dev/null; then
    pass "Current monitoring and the externally approved production qualification both pass."
  else
    qualification_state="$(echo "${health_output}" | jq -r '.productionQualification.state // "unavailable"')"
    qualification_blockers="$(echo "${health_output}" | jq -r '(.productionQualification.blockers // ["qualification-status-unavailable"]) | join(", ")')"
    if [[ "${qualification_state}" == "simulation" ]]; then
      hardware_pending=true
      warn "Production qualification is Simulation (${qualification_blockers}). Physical qualification is still pending."
    else
      fail "Production qualification is ${qualification_state} (${qualification_blockers}). The exact release, site, configuration, receiver, installed chain, timing, recovery, fault, and evidence approval must match."
    fi
  fi
  if echo "${health_output}" | jq -e '.evidenceHealthy == true' >/dev/null; then pass "Evidence recording reports healthy."; else fail "The application reports an evidence storage problem."; fi
  if echo "${health_output}" | jq -e '.receivers | (length > 0 and all(.[]; .connection == "live"))' >/dev/null; then pass "Every configured SDRconnect receiver is live in RF Monitor."; else fail "One or more configured receivers are not live in RF Monitor."; fi
  if echo "${health_output}" | jq -e '.monitoringReady == true' >/dev/null; then pass "Fresh RF spectrum data is available."; elif [[ "${CHECK_SPECTRUM}" == "true" ]]; then fail "RF monitoring is not ready: $(echo "${health_output}" | jq -r '.monitoringIssue // "no current spectrum frames"')"; else hardware_pending=true; warn "RF spectrum commissioning is pending; run sudo rf-monitor commission with the antenna and RSP connected."; fi
  if echo "${health_output}" | jq -e '.storagePolicy.pressure == false' >/dev/null; then pass "No evidence storage pressure is reported."; else fail "Evidence storage is under pressure."; fi
else
  fail "Health endpoint failed on 127.0.0.1:${backend_port}. Check the service logs."
fi
settings_output="$(curl --silent --show-error --max-time 5 "http://127.0.0.1:${backend_port}/api/settings" 2>&1)"
if echo "${settings_output}" | jq -e '.admin.available == true and (.configurationHash | length == 64) and (.catalog.catalogVersion | length > 0)' >/dev/null 2>&1; then
  pass "Protected Settings, operational revision, and frequency catalog are available."
else
  fail "Settings API is incomplete. Reset the Settings password and check the service logs."
fi

section "HTTPS and firewall"
if [[ "${PUBLIC_URL:-}" == https://* ]]; then
  if nginx -t >/dev/null 2>&1; then pass "Nginx configuration is valid."; else fail "Nginx configuration is invalid. Run 'sudo nginx -t' for details."; fi
  systemctl is-active --quiet nginx && pass "Nginx is running for ${PUBLIC_URL}." || fail "Nginx is not running."
  if [[ -n "${CA_CERTIFICATE:-}" && -r "${CA_CERTIFICATE}" ]]; then pass "Local CA certificate is available for operator computers: ${CA_CERTIFICATE}"; fi
  public_health_arguments=(--silent --show-error --max-time 5)
  if [[ -n "${CA_CERTIFICATE:-}" && -r "${CA_CERTIFICATE}" ]]; then public_health_arguments+=(--cacert "${CA_CERTIFICATE}"); fi
  public_health_output="$(curl "${public_health_arguments[@]}" "${PUBLIC_URL%/}/api/health" 2>&1)"
  if [[ $? -eq 0 ]] && echo "${public_health_output}" | jq -e '.schemaVersion == 2 and (.summary.state | type == "string")' >/dev/null 2>&1; then pass "Public HTTPS health endpoint responded with the structured health summary."; else fail "Public HTTPS health check failed. Confirm DNS/certificate name and rerun 'sudo rf-monitor configure-web'. Details: ${public_health_output}"; fi
else
  warn "LAN HTTPS is not configured. Run 'sudo rf-monitor configure-web'."
fi

ufw_status="$(ufw status 2>/dev/null)"
if echo "${ufw_status}" | grep -q '^Status: active'; then
  pass "Ubuntu firewall is active."
  for local_sdr_port in "${SDR_LOCAL_PORTS[@]}"; do
    echo "${ufw_status}" | grep -Eq "${local_sdr_port}/tcp.*DENY|${local_sdr_port} .*DENY" && pass "Direct SDRconnect access on port ${local_sdr_port} is denied by UFW." || warn "A clear UFW deny rule for SDRconnect port ${local_sdr_port} was not found."
  done
  echo "${ufw_status}" | grep -Eq "${backend_port}/tcp.*DENY|${backend_port} .*DENY" && pass "Direct Node.js access is denied by UFW." || warn "A clear UFW deny rule for backend port ${backend_port} was not found."
else
  fail "Ubuntu firewall is inactive. Run 'sudo rf-monitor configure-web' or apply equivalent managed firewall rules."
fi
warn "A second computer must confirm the configured SDRconnect port(s) and ${backend_port} are unreachable from the LAN."

section "Result"
printf '%s passed, %s warnings, %s failed.\n' "${pass_count}" "${warn_count}" "${fail_count}"
if (( fail_count > 0 )); then
  echo "RESULT: NEEDS ATTENTION"
  echo "Run 'sudo rf-monitor logs 200' for service details, correct the FAIL items, then run doctor again."
  exit 1
fi
if [[ "${hardware_pending}" == "true" ]]; then
  echo "RESULT: SOFTWARE READY — HARDWARE COMMISSIONING PENDING"
  exit 0
fi
echo "RESULT: READY"
exit 0
